import "core-js/modules/es.array.push.js";
import axios from 'axios';
export default {
  data() {
    return {
      profileForm: {
        username: '',
        first_name: '',
        last_name: '',
        email: ''
      },
      snackbar: false,
      snackbarMessage: ''
    };
  },
  mounted() {
    this.fetchUserDetails();
  },
  methods: {
    async fetchUserDetails() {
      try {
        const response = await axios.get('/users/api/profile/');
        const userInfo = response.data.user_info;
        userInfo.forEach(item => {
          const key = item.label.toLowerCase().replace(' ', '_');
          if (key in this.profileForm) {
            this.profileForm[key] = item.value;
          }
        });
      } catch (error) {
        console.error('Error fetching user details:', error);
      }
    },
    async saveProfile() {
      try {
        const response = await axios.post('/users/api/profile/edit/', this.profileForm);
        if (response.data.success) {
          this.showSuccessMessage('Profile updated successfully');
          setTimeout(() => {
            this.$router.push('/profile');
          }, 1000);
        } else {
          this.showErrorMessage('Failed to update profile. Please try again.');
        }
      } catch (error) {
        console.error('Error saving profile:', error);
        this.showErrorMessage('An error occurred while saving the profile.');
      }
    },
    cancel() {
      this.$router.push('/profile');
    },
    showSuccessMessage(message) {
      this.snackbarMessage = message;
      this.snackbar = true;
    },
    showErrorMessage(message) {
      this.snackbarMessage = message;
      this.snackbar = true;
    }
  }
};
